package com.ai.mall.identity.application.service;
import com.ai.mall.identity.domain.exception.DomainRuleViolation;import com.ai.mall.identity.domain.repository.AdminUserRepository;import org.springframework.stereotype.Service;
@Service public class AuthorizationDecisionService {private final AdminUserRepository admins;private final AuthorizationQueryService authorization;public AuthorizationDecisionService(AdminUserRepository admins,AuthorizationQueryService authorization){this.admins=admins;this.authorization=authorization;}public boolean permits(long id,String permission){return admins.findById(id).filter(admin->{try{admin.ensureCanSignIn();return true;}catch(DomainRuleViolation ignored){return false;}}).map(admin->authorization.get(id,admin.permissionVersion()).permits(permission)).orElse(false);}}
